function M:OnInit()
    ---当前选择角色
    ---@type RoleData
    self.CurHero = nil
    ---当前英雄属性(可变)
    self.CurHeroAttr = nil
    ---当前英雄属性(不变)
    self.UnChangedHeroAttr = nil
    ---去除装备的属性
    self.NoEquipHeroAttr = nil

    self.ChildSkillList = nil
    ---道具消耗
    self.CostList = {}
    self.exclusiveCost = {}
    ---循环检测计数器
    self.Int_LoopTimer = 0
    ---当前等级
    self.CurSkillLv = 1
    ---技能树选框
    self.Select = nil
    ---当前展示的技能等级
    self.ShowSkillLv = 1

    self.SuccessPanel().gameObject:SetActive(false)
    self.CostItem().gameObject:SetActive(false)
    self.Text_Fortified().gameObject:SetActive(false)
    
    self:InitButton()
    self:AddNoviceEvent()
    Event.Add("ChangeUpdate",Handle(self,self.UpdateCostItem))
end
function M:OnShow()
    ---获取人物界面当前角色的数据
    self.CurHero = RoleCardViewModel.CurrentHero
    self.pData = SkillDetailControl.GetSkillListByID(self.CurHero.id)

    ---去除装备的属性
    self.NoEquipHeroAttr = self.CurHero:GetHeroAttrNoAdditional()
    self.UnChangedHeroAttr = self.CurHero:GetHeroAttrNoAdditional()
    self.LocalNextLv = self.NoEquipHeroAttr.SkillLV + 1
    self.CurHeroAttr = ReadData.GetRoleAttr(self.CurHero.id, self.CurHero.level, self.CurHero.star, self.LocalNextLv, self.CurHero.awaken)
    ---替换技能补丁
    local specialEquip = EquipControl.GetSingleSpecialEquip(self.CurHero.id)
    if specialEquip then
        local skillIndex = specialEquip:GetAdvanceSkillNum()
        local advanceSkillStr = specialEquip:GetSpecialSkill()
        for _,str in pairs(advanceSkillStr) do
            ReadData.ReplaceSkill(str,self.CurHeroAttr,skillIndex)
        end
    end
    --------------
    ---获取消耗
    self:GetCost(self.NoEquipHeroAttr.SkillLV, self.LocalNextLv)
    if #self.CostList > 0 then
        for i = 1, #self.CostList do
            local tItem = ItemControl.GetItemByID(self.CostList[i].itemId)
            self.CostList[i].haveNum = tItem.count
        end
    else
        self.Text_Fortified().gameObject:SetActive(true)
    end
    ---技能等级颜色
    if self.CurHero:CheckHeroEquipIsMax() then
        self.Text_CurSkillLv().color = Color(1,0.772549,0.2235294,1)
    else
        self.Text_CurSkillLv().color = Color(1,1,1,1)
    end
    ---初始化技能等级、名称、布阵
    self:InitRankPanel()
    ---初始化技能列表
    self:ReSkillPanel(self.CurSkillLv)
    ---初始化消耗道具
    self:InitCostPanel()
    ---更新消耗道具
    self:UpdataCostPanel()
    -----更新攻击距离和范围
    --self:UpdataRange(self.CurSkillLv)
    ---初始化技能树
    self:InitSkillTree()
    -----角色阵营图标
    --MgrRes.LoadSprite(self.Img_Logo(), "Attribute/"..self.CurHero.CampiconName)
    ---技能消耗
    local tSkillLv = self.CurSkillLv
    if self.CurSkillLv > self.CurHeroAttr.SkillMaxLV+1 then
        tSkillLv = self.CurHeroAttr.SkillMaxLV+1
    end
    self:CheckSkillCost(tSkillLv)
end
