function M:InitButton()
    Event.Add("BackKey", Handle(self, self.OnBackKey))
    ---返回
    UIEvent.LuaClick(self.Btn_Back().gameObject, Handle(self, function()
        Event.Go("UpdataDetailPanel")
        Event.Remove("BackKey", Handle(self, self.OnBackKey))
        MgrUI.GoBack()
    end))
    ---返回主页
    UIEvent.LuaClick(self.Btn_GoMenu().gameObject, function()
        Event.Remove("BackKey", Handle(self, self.OnBackKey))
        MgrUI.GoBackTo(UID.Home_UI)
    end)
    ---确定
    UIEvent.LuaClick(self.Btn_Shengji().gameObject, function()
        self:OnClickUpgrade()
    end)
    ---点击成功界面响应
    UIEvent.LuaClick(self.Btn_SuccessBack().gameObject, function()
        --self.UnChangedHeroAttr = RoleCardViewModel.CurrentHero:GetHeroAttrNoAdditional()
        --if self.UnChangedHeroAttr.SkillLV >= self.UnChangedHeroAttr.SkillMaxLV then
        --    MgrUI.GoBack()
        --    return
        --end
        self.SuccessPanel().gameObject:SetActive(false)
    end)
end

---初始化技能等级、名称、布阵
function M:InitRankPanel()
    local tSkillData = SkillDetailControl.GetSkillListByID(self.CurHero.id)
    local specialEquip = EquipControl.GetSingleSpecialEquip(self.CurHero.id)
    tSkillData = SkillDetailControl.SortSkillList(tSkillData,specialEquip)    ---根据角色进阶共鸣装备替换技能简略表
    self.Text_SkillName().text = tSkillData[1].TotleName
    local lv = self.CurHero.skillLevel
    if self.CurHero:CheckHeroEquipIsMax() then
        lv = lv + 1
    end
    --self.CurSkillLv = self.CurHero:GetHeroShowSkillLv() + 1
    self.CurSkillLv = lv + 1
    --if self.CurSkillLv > 10 then
    --    self.CurSkillLv = 10
    --end
    ---显示下一级的技能
    local tCurSkill = self.CurSkillLv > self.CurHeroAttr.SkillMaxLV+1 and self.CurHeroAttr.SkillMaxLV+1 or self.CurSkillLv
    self.Text_CurSkillLv().text = tCurSkill
end

---初始化技能列表
function M:ReSkillPanel(_skillLv)
    local tSkillLv = _skillLv
    if _skillLv > 10 then
        tSkillLv = 10
    end
    local tCurHeroAttr = ReadData.GetRoleAttr(self.CurHero.id, self.CurHero.level, self.CurHero.star, tSkillLv, self.CurHero.awaken)
    ---替换技能补丁
    local specialEquip = EquipControl.GetSingleSpecialEquip(self.CurHero.id)
    if specialEquip then
    local skillIndex = specialEquip:GetAdvanceSkillNum()
        local advanceSkillStr = specialEquip:GetSpecialSkill()
        for _,str in pairs(advanceSkillStr) do
            ReadData.ReplaceSkill(str,tCurHeroAttr,skillIndex)
        end
    end
    -------------------
    local tSkillList = { [1] = { tCurHeroAttr.Skill_1_example, tCurHeroAttr.Skill_1 },
                         [2] = { tCurHeroAttr.Skill_2_example, tCurHeroAttr.Skill_2 },
                         [3] = { tCurHeroAttr.Skill_3_example, tCurHeroAttr.Skill_3 },
                         [4] = { tCurHeroAttr.Skill_4_example, tCurHeroAttr.Skill_4 },
                         [5] = { tCurHeroAttr.Skill_5_example, tCurHeroAttr.Skill_5 },
                        }
    self.ChildSkillList = {}
    local id = 0
    for i, skillExample in ipairs(tSkillList) do
        for n = 1, #skillExample[2] do
            if skillExample[2][n][3] and skillExample[1][n] then
                local tId = #self.ChildSkillList
                if id ~= i then
                    tId = tId+1
                    self.ChildSkillList[tId] = {}
                    id = i
                end
                table.insert(self.ChildSkillList[tId], skillExample[1][n])
            end
        end
    end

    self.ShowSkillLv = tSkillLv
    self.SkillScroll01():ClearCells()
    ---注册左侧子页签滑块
    self.SkillScroll01():SetLuaCellEvent(Handle(self, self.SkillCell))
    self.SkillScroll01().totalCount = #self.ChildSkillList == 0 and 1 or #self.ChildSkillList
    self.SkillScroll01():RefillCells()
end

function M:InitSkillTree()
    local tCurSkillTree = self.SkillTreeList().transform:Find(self.CurHeroAttr.SkillTreeName)
    if tCurSkillTree == nil then
        return
    end
    self.SkillTreeScroll01().prefabSource.poolPrefab = tCurSkillTree.gameObject
    self.SkillTreeScroll01():SetLuaCellEvent(Handle(self, self.SkillTreeCell))
    self.SkillTreeScroll01():RefillCells()
end

function M:SkillCell(trans, idx)
    ---传入数据
    --self:SkillDetail(trans.gameObject, self.ChildSkillList[idx], idx)
    trans:GetComponent("UITemplate"):SetData({ self.CurHero,self.CurHeroAttr,self.ChildSkillList[idx],self.ShowSkillLv,"ChildSkill" })
    Tools.ReContentSizeGroup(self.SkillContent().gameObject)
end
---技能详情列表
function M:SkillDetail(_obj, _data, _idx)
    local tSkillName = CJNUIMgr.GetSunUseName(_obj, "Text_Jinengming"):GetComponent("TextMeshProUGUI")
    local tSkillTips = CJNUIMgr.GetSunUseName(_obj, "Text_Jinengshuoming"):GetComponent("TextMeshProUGUI")
    local tMatter = CJNUIMgr.GetSunUseName(_obj, "Text_Matter"):GetComponent("TextMeshProUGUI")
    local tSkillGg = CJNUIMgr.GetSunUseName(_obj, "Img_Jinengdi"):GetComponent("Image")
    local tTagPanel = CJNUIMgr.GetSunUseName(_obj, "TagPanel")
    local tSkillTag = CJNUIMgr.GetSunUseName(_obj, "Img_Tag")
    local tException = CJNUIMgr.GetSunUseName(_obj, "Img_Exception")
    local tBtnSkillDetail = CJNUIMgr.GetSunUseName(_obj, "Btn_SkillDetailTip")
    tException.gameObject:SetActive(false)
    ---技能名
    tSkillName.text = _data.Name
    ---技能说明
    tSkillTips.text = _data.Explain
    ---技能标签
    local tagType = {}
    table.insert(tagType, SkilltypeoneLocalData.tab[_data.Skilltype1])
    table.insert(tagType, SkilltypetwoLocalData.tab[_data.Skilltype2])
    Tools.ClearAllChild(tTagPanel.gameObject)
    for i = 1, #tagType do
        local tempObj = GameObject.Instantiate(tSkillTag.gameObject, tTagPanel.transform)
        local tagStr = tempObj.transform:Find("Text_Tag"):GetComponent("TextMeshProUGUI")
        tagStr.text = tagType[i][2]
        tempObj:SetActive(true)
    end
    tSkillTag.gameObject:SetActive(false)
    ---长按查看例外事项
    local isTouch = false
    UIEvent.LuaPressClick(tSkillGg.gameObject, function()
        if isTouch or not tBtnSkillDetail.gameObject.activeSelf then
            return
        end
        isTouch = true
        tException.gameObject:SetActive(true)
        MgrTimer.AddRepeat("ExceptionTouch", 0, function()
            if UIEvent.GetButton_Up() == true then
                MgrTimer.Cancel("ExceptionTouch")
                tException.gameObject:SetActive(false)
                isTouch = false
            end
        end, -1, nil)
        end,nil,tSkillGg)
    ---更新框体宽高
    _obj.gameObject:GetComponent("SkillBound"):UpdateSize(function()
        if #self.ChildSkillList == _idx then
            Tools.ReContentSizeGroup(self.SkillContent().gameObject)
        end
    end)
    ---例外事项
    local exception = string.split(_data.Exception,"@")
    if exception[1] == "0" or #exception == 0 then
        tBtnSkillDetail.gameObject:SetActive(false)
        return
    end
    local text = ""
    for i = 1, #exception do
        text = text .. SkillexceptionLocalData.tab[tonumber(exception[i])][2] .. "\n"
    end
    tMatter.text = text
end

