---技能树
function M:SkillTree(_obj)
    local CurSelect = nil
    local CurSelectText = nil
    local Select = nil
    --self.Select = CJNUIMgr.GetSunUseName(_obj, "Xzkuang")
    local tPointSkillGroup = nil
    local tEffect = {}
    local tBlue = nil
    local tWhite = nil
    
    if self.UnChangedHeroAttr.PointSkillGroup and self.UnChangedHeroAttr.PointSkillGroup ~= "0" then
        tPointSkillGroup = string.split(self.UnChangedHeroAttr.PointSkillGroup,',')
    end
    for i = 1, self.UnChangedHeroAttr.SkillMaxLV+1 do
        --if i <= self.UnChangedHeroAttr.SkillMaxLV then
        --    local LineList = CJNUIMgr.GetSunUseName(_obj, "Xian"..i).transform:Find("Img_xian_H")
        --    if i < self.CurSkillLv-1 then
        --        LineList.gameObject:SetActive(true)
        --    else
        --        LineList.gameObject:SetActive(false)
        --    end
        --end
        
        local tSkillBtn = CJNUIMgr.GetSunUseName(_obj, "SkillPrefab"..i)
        local BtnNomal = tSkillBtn.transform:Find("bg_skill_d"):GetComponent("Image")
        local BtnLight = tSkillBtn.transform:Find("bg_skill_n"):GetComponent("Image")
        local BtnSelect = tSkillBtn.transform:Find("bg_skill_p"):GetComponent("Image")
        local SelectEff = tSkillBtn.transform:Find("bg_skill_checkbox")
        local BtnText = tSkillBtn.transform:Find("Text_SkillLv"):GetComponent("TextMeshProUGUI")
        ---技能树按钮图标
        if tPointSkillGroup and Global.Contains(tPointSkillGroup,tostring(i)) then
            MgrRes.LoadSprite(BtnNomal,"SkillTree/bg_skill_b_d",nil,true)
            MgrRes.LoadSprite(BtnLight,"SkillTree/bg_skill_b_n",nil,true)
            MgrRes.LoadSprite(BtnSelect,"SkillTree/bg_skill_b_p",nil,true)

            tEffect[i] = tSkillBtn.transform:Find(self.ui_TX_040().name.."(Clone)")
            if tEffect[i] == nil then
                tEffect[i] = GameObject.Instantiate(self.ui_TX_040().gameObject, tSkillBtn.transform)
                tEffect[i].transform.localPosition = Vector3.zero
                tEffect[i].gameObject:SetActive(true)
            end
        else
            MgrRes.LoadSprite(BtnNomal,"SkillTree/bg_skill_s_d",nil,true)
            MgrRes.LoadSprite(BtnLight,"SkillTree/bg_skill_s_n",nil,true)
            MgrRes.LoadSprite(BtnSelect,"SkillTree/bg_skill_s_p",nil,true)
        end
        ---按钮名
        BtnText.text = i
        ---按钮状态
        if i < self.CurSkillLv then
            BtnNomal.gameObject:SetActive(false)
            BtnLight.gameObject:SetActive(true)
            BtnSelect.gameObject:SetActive(false)
            SelectEff.gameObject:SetActive(false)
            BtnText.color = Color(1,1,1,1)
        else
            BtnLight.gameObject:SetActive(false)
            BtnSelect.gameObject:SetActive(false)
            SelectEff.gameObject:SetActive(false)
            BtnText.color = Color(1,1,1,0.5)
        end
        ---选框的坐标
        if i == self.CurSkillLv or (i == self.UnChangedHeroAttr.SkillMaxLV+1 and i < self.CurSkillLv) then
            BtnSelect.gameObject:SetActive(true)
            SelectEff.gameObject:SetActive(true)

            Select = SelectEff
            --Select.transform.localPosition = tSkillBtn.transform.localPosition
            BtnText.color = Color(1,1,1,1)

            CurSelect = BtnSelect
            CurSelectText = BtnText
            if tEffect[i] then
                tBlue = tEffect[i].transform:Find("lan")
                tWhite = tEffect[i].transform:Find("bai")

                tBlue.gameObject:SetActive(true)
                tWhite.gameObject:SetActive(false)
            end
        else
            if tEffect[i] then
                tEffect[i].transform:Find("lan").gameObject:SetActive(false)
                tEffect[i].transform:Find("bai").gameObject:SetActive(true)
            end
        end
        ---技能树按钮
        UIEvent.LuaClick(tSkillBtn.gameObject, function()
            if CurSelect == BtnSelect then
                return
            end
            ---更新选中高亮
            CurSelect.gameObject:SetActive(false)
            CurSelect = BtnSelect
            CurSelect.gameObject:SetActive(true)
            ---更新选中文字
            if tonumber(CurSelectText.text) < self.CurSkillLv then
                CurSelectText.color = Color(1,1,1,1)
            else
                CurSelectText.color = Color(1,1,1,0.5)
            end
            CurSelectText = BtnText
            CurSelectText.color = Color(1,1,1,1)
            ---更新大技能特效
            if tBlue then
                tBlue.gameObject:SetActive(false)
                tWhite.gameObject:SetActive(true)
                if tEffect[i] then
                    tBlue = tEffect[i].transform:Find("lan")
                    tWhite = tEffect[i].transform:Find("bai")

                    tBlue.gameObject:SetActive(true)
                    tWhite.gameObject:SetActive(false)
                else
                    tBlue = nil
                    tWhite = nil
                end
            else
                if tEffect[i] then
                    tBlue = tEffect[i].transform:Find("lan")
                    tWhite = tEffect[i].transform:Find("bai")

                    tBlue.gameObject:SetActive(true)
                    tWhite.gameObject:SetActive(false)
                end
            end
            ---更新选框
            --Select.transform.localPosition = tSkillBtn.transform.localPosition
            Select.gameObject:SetActive(false)
            Select = SelectEff
            Select.gameObject:SetActive(true)
            ---技能等级
            self.Text_CurSkillLv().text = CurSelectText.text

            ---初始化技能列表
            self:ReSkillPanel(tonumber(CurSelectText.text))
            -----更新攻击距离和范围
            --self:UpdataRange(tonumber(CurSelectText.text))
            ---技能消耗
            self:CheckSkillCost(tonumber(CurSelectText.text))
        end)
    end
end
---技能消耗
function M:CheckSkillCost(_skillLv)
    ---更新技能消耗显示
    if _skillLv < self.CurSkillLv then
        self.FortifyPanel().gameObject:SetActive(false)
        self.Text_Fortified().gameObject:SetActive(true)
        self.Text_Fortified().text = MgrLanguageData.GetLanguageByKey("ui_yangcheng_text148")
    elseif _skillLv == self.CurSkillLv then
        if _skillLv == self.CurHeroAttr.SkillMaxLV+1 and not self.CurHero:CheckHeroEquipIsMax() then
            self.FortifyPanel().gameObject:SetActive(false)
            self.Text_Fortified().gameObject:SetActive(true)
            self.Text_Fortified().text = MgrLanguageData.GetLanguageByKey("ui_yangcheng_text146")
            return
        end
        self.FortifyPanel().gameObject:SetActive(true)
        self.Text_Fortified().gameObject:SetActive(false)
    else
        self.FortifyPanel().gameObject:SetActive(false)
        self.Text_Fortified().gameObject:SetActive(false)
    end
end

