---生成子物体
function M:InitPanel(_StarLV, _Root, _Prefab)
    Tools.ClearAllChild(_Root)
    local tempObjList = {}
    for i = 1, _StarLV, 1 do
        tempObjList[i] = self:CreatInPanel(_Root, _Prefab)
    end

    return tempObjList
end
---创建子物体
function M:CreatInPanel(_Root, _Prefab)
    local UnJuxingStar = self:CreatGo(_Prefab, _Root)
    UnJuxingStar.transform.localPosition = Vector3(UnJuxingStar.transform.localPosition.x, UnJuxingStar.transform.localPosition.y, 0)

    return UnJuxingStar
end
---创建一个物体
function M:CreatGo(_Prefab, _Root)
    if _Prefab == nil then
        print(_Prefab)
    end
    local tempObj = GameObject.Instantiate(_Prefab, _Root.transform)
    tempObj.gameObject:SetActive(true)
    tempObj.transform.localPosition = Vector3.zero
    return tempObj
end

---升级成功后,刷新界面
function M:RefreshUI()
    self.UnChangedHeroAttr = RoleCardViewModel.CurrentHero:GetHeroAttrNoAdditional()
    self.NoEquipHeroAttr = self.CurHero:GetHeroAttrNoAdditional()
    self.LocalNextLv = self.NoEquipHeroAttr.SkillLV + 1
    self.CurHeroAttr = ReadData.GetRoleAttr(self.CurHero.id, self.CurHero.level, self.CurHero.star, self.LocalNextLv, self.CurHero.awaken)
    ---替换技能补丁
    local specialEquip = EquipControl.GetSingleSpecialEquip(self.CurHero.id)
    if specialEquip then
        local skillIndex = specialEquip:GetAdvanceSkillNum()
        local advanceSkillStr = specialEquip:GetSpecialSkill()
        for _,str in pairs(advanceSkillStr) do
            ReadData.ReplaceSkill(str,self.CurHeroAttr,skillIndex)
        end
    end
    --------------
    self:ClearCostNum()
    ---获取消耗
    self:GetCost(self.NoEquipHeroAttr.SkillLV, self.LocalNextLv)
    ---初始化技能等级、名称、布阵
    self:InitRankPanel()
    ---初始化技能列表
    self:ReSkillPanel(self.CurSkillLv)
    ---初始化消耗道具
    self:InitCostPanel()
    ---更新消耗道具
    self:UpdataCostPanel()
    -----更新攻击距离和范围
    --self:UpdataRange(self.CurSkillLv)
    ---更新技能树
    self.SkillTreeScroll01():RefreshCells()
    ---技能消耗
    local tSkillLv = self.CurSkillLv
    if self.CurSkillLv > self.CurHeroAttr.SkillMaxLV+1 then
        tSkillLv = self.CurHeroAttr.SkillMaxLV+1
    end
    self:CheckSkillCost(tSkillLv)
    ---刷新技能树位置
    MgrTimer.AddDelayNoName(0.35,function()
        self:OnShowFinish()
    end)
end

function M:UpdateCostItem()
    ---初始化消耗道具
    self:InitCostPanel()
    ---更新消耗道具
    self:UpdataCostPanel()
end

function M:OnClose()
    Event.CheckClear("ChangeUpdate")
end
function M:OnBackKey()
    if not MgrUI.IsPopOpen() then
        Event.Remove("BackKey", Handle(self, self.OnBackKey))
        MgrUI.GoBack()
    end
end
return M